CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction
COMMENT 'Claims movements translated to core claim transactions. Payment rows become INDEMNITY_PAYMENT and ALSO generate a matching negative CASE_RESERVE_MOVEMENT, because the core convention is that a payment releases the reserve it pays. Without this translation the claims-system view double-counts outstanding. Grain: One row per movement, plus one reserve release per payment (core convention). Conformed from CLM_MOTOR (lr_serverless_aws_us_catalog.bricksurance_src_claims.clm_movement) by mapping clm_motor; column names and definitions are the core concept claim_transaction. Owner Head of Motor Claims; certified.'
AS
SELECT concat('CLM_MOTOR:', movement_id) AS claim_transaction_id,
       concat('CLM_MOTOR:', claim_ref) AS claim_id,
       CASE movement_type WHEN 'PAID' THEN 'INDEMNITY_PAYMENT' WHEN 'RESERVE' THEN 'CASE_RESERVE_MOVEMENT'
                          WHEN 'RECOVERY' THEN 'RECOVERY' WHEN 'FEE' THEN 'EXPENSE_PAYMENT' END AS claim_transaction_type_code,
       amount, 'GBP' AS currency_code, movement_dt AS transaction_date, 'CLM_MOTOR' AS source_system_code,
       head_of_damage AS head_of_damage_code,
       CASE head_of_damage WHEN 'BODILY_INJURY' THEN 'THIRD_PARTY_INJURY' WHEN 'TP_PROPERTY' THEN 'THIRD_PARTY_PROPERTY'
                           ELSE 'OWN_DAMAGE' END AS claim_feature_type_code
FROM lr_serverless_aws_us_catalog.bricksurance_src_claims.clm_movement
UNION ALL
SELECT concat('CLM_MOTOR:', movement_id, ':REL'), concat('CLM_MOTOR:', claim_ref), 'CASE_RESERVE_MOVEMENT',
       -amount, 'GBP', movement_dt, 'CLM_MOTOR', head_of_damage,
       CASE head_of_damage WHEN 'BODILY_INJURY' THEN 'THIRD_PARTY_INJURY' WHEN 'TP_PROPERTY' THEN 'THIRD_PARTY_PROPERTY'
                           ELSE 'OWN_DAMAGE' END
FROM lr_serverless_aws_us_catalog.bricksurance_src_claims.clm_movement
WHERE movement_type = 'PAID';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.claim_transaction_id IS 'Identifier for the claim transaction.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.claim_id IS 'Claim the movement belongs to.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.claim_transaction_type_code IS 'Kind of financial movement. FEE is allocated claims handling cost (ALAE); RECOVERY is negative in both systems.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.amount IS 'Signed amount in the transaction currency. Reserve increases positive, reserve releases negative; payments positive; recoveries negative from the insurer''s cost perspective.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.currency_code IS 'Currency of the amount.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.transaction_date IS 'Date the movement was booked.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.source_system_code IS 'System of record the movement originates from.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.head_of_damage_code IS 'Claims-system head of damage: VEHICLE_REPAIR, THEFT_TOTAL_LOSS, TP_PROPERTY, BODILY_INJURY, GLASS, FIRE_TOTAL_LOSS. The level at which repair-cost and injury questions are answered.';

COMMENT ON COLUMN lr_serverless_aws_us_catalog.bricksurance_semantics.vw_motor_claim_transaction.claim_feature_type_code IS 'Head of damage rolled up to the core claim feature type (OWN_DAMAGE, THIRD_PARTY_PROPERTY, THIRD_PARTY_INJURY).';

